-- Esquema inicial. Generado a partir de las entidades JPA (modulo entidades).
create table administradores (id uuid not null, usuario_id uuid not null unique, primary key (id));
create table archivos (tamano bigint not null, evento_incidente_id uuid, id uuid not null, extension varchar(255) not null, primary key (id));
create table auditorias_infraccion (timestamp timestamp(6) with time zone not null, id uuid not null, infraccion_id uuid not null, usuario_id uuid, accion varchar(255) not null, fundamento text, primary key (id));
create table autoridades (id uuid not null, usuario_id uuid not null unique, primary key (id));
create table choferes (id uuid not null, usuario_id uuid not null unique, primary key (id));
create table choferes_empresas (chofer_id uuid not null, empresa_id uuid not null, primary key (chofer_id, empresa_id));
create table configuraciones_sistema (periodo_descargo numeric(21,0) not null, periodo_maximo_viaje numeric(21,0) not null, tolerancia_desvio_ruta numeric(10,2) not null, tolerancia_diferencia_peso_balanzas numeric(7,3) not null, tolerancia_exceso_carga numeric(7,3) not null, id uuid not null, primary key (id));
create table descargos (fecha date not null, id uuid not null, infraccion_id uuid not null unique, descripcion text not null, primary key (id));
create table empresas (id uuid not null, direccion varchar(255) not null, nombre varchar(255) not null, numero varchar(255) not null unique, razon_social varchar(255) not null, rubro varchar(255) not null check ((rubro in ('AGROPECUARIO','ALIMENTOS','COMBUSTIBLES','CONSTRUCCION','FORESTAL','OTRO'))), primary key (id));
create table encargados_empresa (id uuid not null, usuario_id uuid not null unique, primary key (id));
create table encargados_empresa_empresas (empresa_id uuid not null, encargado_empresa_id uuid not null, primary key (empresa_id, encargado_empresa_id));
create table eventos_viaje (autogenerado boolean, peso numeric(12,3), timestamp timestamp(6) with time zone not null, guia_id uuid not null, id uuid not null, tipo_evento varchar(31) not null check ((tipo_evento in ('CARGA','DESCARGA','FIN','INCIDENTE','INICIO'))), descripcion text, primary key (id));
create table funcionarios (id uuid not null, usuario_id uuid not null unique, primary key (id));
create table guias (fecha date not null, peso_carga numeric(12,3) not null, chofer_id uuid, empresa_id uuid not null, id uuid not null, vehiculo_id uuid, destino varchar(255) not null, origen varchar(255) not null, rubro_cliente varchar(255) not null check ((rubro_cliente in ('AGROPECUARIO','ALIMENTOS','COMBUSTIBLES','CONSTRUCCION','FORESTAL','OTRO'))), tipo_carga varchar(255) not null check ((tipo_carga in ('GENERAL','GRANEL','REFRIGERADA','PELIGROSA'))), primary key (id));
create table infracciones (empresa_id uuid not null, id uuid not null, vehiculo_id uuid, estado varchar(255) not null check ((estado in ('DETECTADA','NOTIFICADA','EN_DESCARGO','DESESTIMADA','CONFIRMADA'))), tipo varchar(255) not null check ((tipo in ('EXCESO_DE_CARGA_EXPLICITO','EXCESO_DE_CARGA_IMPLICITO','VEHICULO_SIN_HABILITACION_VIGENTE','VIAJE_SIN_GUIA','DESVIO_DE_RUTA','EVENTO_NO_NOTIFICADO','SECUENCIA_DE_EVENTOS_IMPOSIBLE'))), evidencia jsonb, primary key (id));
create table inspecciones_tecnicas_vehiculares (fecha_vencimiento date not null, archivo_id uuid not null unique, id uuid not null, vehiculo_id uuid not null unique, primary key (id));
create table notificaciones (leida boolean not null, timestamp timestamp(6) with time zone not null, encargado_empresa_id uuid not null, id uuid not null, infraccion_id uuid not null, primary key (id));
create table permisos (archivo_id uuid not null unique, empresa_id uuid not null, id uuid not null, primary key (id));
create table permisos_nacionales_circulacion (fecha_vencimiento date not null, archivo_id uuid not null unique, id uuid not null, vehiculo_id uuid not null unique, numero varchar(255) not null, primary key (id));
create table resoluciones (fecha date not null, id uuid not null, infraccion_id uuid not null unique, fundamento text not null, primary key (id));
create table usuarios (fecha_nacimiento date not null, id uuid not null, apellido varchar(255) not null, ci varchar(255) not null unique, contrasenia varchar(255) not null, email varchar(255) not null unique, nombre varchar(255) not null, primary key (id));
create table vehiculos (capacidad numeric(12,3) not null, peso numeric(12,3) not null, empresa_id uuid not null, id uuid not null, marca varchar(255) not null, matricula varchar(255) not null unique, modelo varchar(255) not null, primary key (id));
